[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Web Summit Lisbon 2026 — Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Space+Grotesk:wght@400;500;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --cyan: #00e5ff;
    --magenta: #ff006e;
    --neon-green: #39ff14;
    --deep-blue: #0a0e27;
    --dark-bg: #050816;
    --card-bg: rgba(255,255,255,0.04);
    --card-border: rgba(255,255,255,0.08);
    --text-primary: #ffffff;
    --text-secondary: rgba(255,255,255,0.7);
    --text-muted: rgba(255,255,255,0.45);
  }

  body {
    width: 1080px;
    height: 1920px;
    background: var(--dark-bg);
    font-family: 'Inter', 'Space Grotesk', sans-serif;
    color: var(--text-primary);
    overflow: hidden;
    position: relative;
  }

  /* Background effects */
  .bg-gradient {
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background:
      radial-gradient(ellipse 80% 50% at 20% 10%, rgba(0,229,255,0.12) 0%, transparent 60%),
      radial-gradient(ellipse 60% 40% at 80% 30%, rgba(255,0,110,0.10) 0%, transparent 55%),
      radial-gradient(ellipse 70% 35% at 50% 85%, rgba(57,255,20,0.06) 0%, transparent 50%),
      radial-gradient(ellipse 100% 100% at 50% 0%, rgba(10,14,39,1) 0%, rgba(5,8,22,1) 100%);
    z-index: 0;
  }

  /* Geometric decorative elements */
  .geo-line {
    position: absolute;
    z-index: 1;
    opacity: 0.15;
  }
  .geo-line-1 {
    top: 180px; left: 0; right: 0; height: 1px;
    background: linear-gradient(90deg, transparent, var(--cyan), transparent);
  }
  .geo-line-2 {
    top: 0; bottom: 0; left: 60px; width: 1px;
    background: linear-gradient(180deg, transparent, var(--magenta) 30%, transparent 70%);
  }
  .geo-line-3 {
    top: 0; bottom: 0; right: 60px; width: 1px;
    background: linear-gradient(180deg, transparent 20%, var(--cyan) 50%, transparent 80%);
  }

  /* Grid pattern overlay */
  .grid-overlay {
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background-image:
      linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
    background-size: 60px 60px;
    z-index: 1;
  }

  /* Abstract light trails */
  .light-trail {
    position: absolute;
    z-index: 1;
    border-radius: 50%;
    filter: blur(80px);
  }
  .light-trail-1 {
    width: 400px; height: 400px;
    top: -100px; right: -100px;
    background: radial-gradient(circle, rgba(0,229,255,0.15), transparent 70%);
  }
  .light-trail-2 {
    width: 300px; height: 300px;
    bottom: 200px; left: -80px;
    background: radial-gradient(circle, rgba(255,0,110,0.12), transparent 70%);
  }
  .light-trail-3 {
    width: 250px; height: 250px;
    top: 50%; right: 10%;
    background: radial-gradient(circle, rgba(57,255,20,0.08), transparent 70%);
  }

  .content {
    position: relative;
    z-index: 10;
    padding: 64px 72px;
    height: 100%;
    display: flex;
    flex-direction: column;
  }

  /* ===== HEADER ===== */
  .header {
    text-align: center;
    margin-bottom: 24px;
  }

  .event-badge {
