  .event-date-location .separator {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: var(--cyan);
  }

  .event-date-location .date {
    color: var(--cyan);
    font-weight: 700;
    font-size: 22px;
  }

  /* ===== TICKET OFFER (hero CTA) ===== */
  .ticket-offer {
    margin: 28px 0 32px;
    padding: 36px 40px;
    border-radius: 20px;
    background: linear-gradient(135deg, rgba(255,0,110,0.12) 0%, rgba(0,229,255,0.08) 100%);
    border: 1px solid rgba(255,0,110,0.3);
    position: relative;
    overflow: hidden;
    text-align: center;
  }

  .ticket-offer::before {
    content: '';
    position: absolute;
    top: -2px; left: -2px; right: -2px; bottom: -2px;
    border-radius: 22px;
    background: linear-gradient(135deg, var(--magenta), var(--cyan));
    z-index: -1;
    opacity: 0.4;
  }

  .ticket-offer::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    border-radius: 20px;
    background: linear-gradient(135deg, rgba(5,8,22,0.92), rgba(10,14,39,0.95));
    z-index: -1;
  }

  .offer-urgency {
    display: inline-block;
    background: var(--magenta);
    color: white;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    padding: 6px 20px;
    border-radius: 100px;
    margin-bottom: 18px;
  }

  .offer-headline {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 64px;
    font-weight: 700;
    line-height: 1;
    letter-spacing: -2px;
    margin-bottom: 6px;
  }

  .offer-headline .big {
    background: linear-gradient(135deg, var(--magenta), #ff6b6b);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .offer-sub {
    font-size: 22px;
    font-weight: 500;
    color: var(--text-secondary);
    margin-bottom: 14px;
  }

  .offer-savings {
    font-size: 28px;
    font-weight: 700;
    color: var(--cyan);
    letter-spacing: 1px;
  }

  .cta-button {
    display: inline-block;
    margin-top: 22px;
    padding: 18px 56px;
    background: linear-gradient(135deg, var(--magenta), #ff3d7f);
