      0 0 60px rgba(255,0,110,0.15);
  }

  /* ===== METRICS ROW ===== */
  .metrics-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 32px;
  }

  .metric-card {
    text-align: center;
    padding: 24px 12px;
    border-radius: 16px;
    background: var(--card-bg);
    border: 1px solid var(--card-border);
  }

  .metric-value {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 40px;
    font-weight: 700;
    line-height: 1;
    margin-bottom: 6px;
  }

  .metric-value.cyan { color: var(--cyan); }
  .metric-value.magenta { color: var(--magenta); }
  .metric-value.green { color: var(--neon-green); }
  .metric-value.white { color: #fff; }

  .metric-label {
    font-size: 13px;
    font-weight: 500;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  /* ===== SPEAKERS ===== */
  .section-title {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 15px;
    font-weight: 600;
    text-transform: uppercase;
