    background: radial-gradient(circle, rgba(57,255,20,0.07), transparent 70%);
  }
  .light-trail-4 {
    width: 400px; height: 250px;
    top: 15%; left: -80px;
    background: radial-gradient(circle, rgba(255,0,110,0.06), transparent 70%);
  }

  .content {
    position: relative;
    z-index: 10;
    padding: 56px 72px 48px;
    height: 100%;
    display: flex;
    flex-direction: column;
  }

  /* ===== HEADER ===== */
  .header {
    text-align: center;
    margin-bottom: 20px;
  }

  .event-badge {
    display: inline-block;
    padding: 8px 24px;
    border: 1px solid var(--cyan);
    border-radius: 100px;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--cyan);
    margin-bottom: 24px;
    background: rgba(0,229,255,0.06);
  }

  .event-title {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 86px;
    font-weight: 700;
    line-height: 0.92;
    letter-spacing: -3px;
    margin-bottom: 8px;
    background: linear-gradient(180deg, #ffffff 0%, rgba(255,255,255,0.85) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .event-title .accent {
    font-size: 92px;
    background: linear-gradient(135deg, var(--cyan) 0%, #00b8d4 50%, var(--magenta) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .event-subtitle {
    font-size: 20px;
    font-weight: 300;
    color: var(--text-secondary);
    letter-spacing: 1px;
    margin-top: 10px;
  }

  .event-date-location {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 24px;
    margin-top: 20px;
    font-size: 20px;
    font-weight: 500;
    color: var(--text-primary);
  }

  .event-date-location .separator {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: var(--cyan);
  }

  .event-date-location .date {
    color: var(--cyan);
    font-weight: 700;
    font-size: 22px;
  }

  /* ===== TICKET OFFER (hero CTA) ===== */
  .ticket-offer {
    margin: 24px 0 28px;
    padding: 32px 40px 36px;
    border-radius: 20px;
    background: linear-gradient(135deg, rgba(255,0,110,0.12) 0%, rgba(0,229,255,0.08) 100%);
    border: 1px solid rgba(255,0,110,0.3);
    position: relative;
    overflow: hidden;
    text-align: center;
  }

  .ticket-offer::before {
    content: '';
    position: absolute;
    top: -2px; left: -2px; right: -2px; bottom: -2px;
    border-radius: 22px;
    background: linear-gradient(135deg, var(--magenta), var(--cyan));
    z-index: -1;
    opacity: 0.4;
  }

  .ticket-offer::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    border-radius: 20px;
    background: linear-gradient(135deg, rgba(5,8,22,0.92), rgba(10,14,39,0.95));
    z-index: -1;
  }

  .offer-urgency {
    display: inline-block;
    background: var(--magenta);
    color: white;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    padding: 6px 20px;
    border-radius: 100px;
    margin-bottom: 16px;
  }

  .offer-headline {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 68px;
    font-weight: 700;
    line-height: 1;
    letter-spacing: -2px;
    margin-bottom: 6px;
  }

  .offer-headline .big {
    background: linear-gradient(135deg, var(--magenta), #ff6b6b);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .offer-sub {
    font-size: 20px;
    font-weight: 500;
    color: var(--text-secondary);
    margin-bottom: 12px;
  }

  .offer-savings {
    font-size: 28px;
    font-weight: 700;
    color: var(--cyan);
    letter-spacing: 1px;
  }

  .cta-button {
